CREATE TABLE `dss_workflow_node_content` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `node_key` varchar(64) NOT NULL COMMENT '节点Key',
  `node_id` varchar(64) NOT NULL COMMENT '节点Id',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `modify_time` datetime  DEFAULT NULL COMMENT '更新时间',
  `modify_user` varchar(255) DEFAULT NULL COMMENT '更新人',
  `job_type` varchar(255) DEFAULT NULL COMMENT '节点类型',
  `orchestrator_id` bigint(20) NOT NULL COMMENT '编排Id',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='工作流节点表';


CREATE TABLE `dss_workflow_node_content_to_ui` (
  `content_id` bigint(20) NOT NULL COMMENT '编排Id',
  `node_ui_key` varchar(64) NOT NULL COMMENT '节点Key',
  `node_ui_value` text NOT NULL COMMENT '属性值',
  PRIMARY KEY (`content_id`, `node_ui_key`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='工作流节点属性表';


CREATE TABLE `dss_workflow_node_meta` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `orchestrator_id` bigint(20) NOT NULL COMMENT '编排Id',
  `proxy_user` varchar(64) DEFAULT NULL COMMENT '代理用户',
  `meta_resource` varchar(255) DEFAULT NULL COMMENT '资源文件',
  `global_var` TEXT COMMENT '全局变量',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='工作流配置表';

-- copilot_sit.copilot_collection definition

CREATE TABLE IF NOT EXISTS `copilot_collection` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `collection_name` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT 'collection_name',
  `top_n` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT 'top_n',
  `dept_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT 'dept_id',
  `dept_name` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT 'dept_name',
  `status` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT 'status',
  `llmclient_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT 'llmclient_id',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `last_access_time` datetime DEFAULT NULL COMMENT '最近一次提问时间',
  `last_update_time` datetime DEFAULT NULL COMMENT '最近一次更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


-- copilot_sit.copilot_server_chat definition

CREATE TABLE  IF NOT EXISTS  `copilot_server_chat` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `chat_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '聊天窗id',
  `session_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '聊天窗归属的会话id',
  `username` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '用户名',
  `prompt_type` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT 'prompt类型',
  `chat_name` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '聊天窗名',
  `store_path` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '聊天文件存储路径',
  `create_time` datetime DEFAULT NULL COMMENT '聊天窗口创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `last_access_time` datetime DEFAULT NULL COMMENT '最近一次提问时间',
  `last_update_time` datetime DEFAULT NULL COMMENT '最近一次更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


-- copilot_sit.copilot_server_context definition

CREATE TABLE  IF NOT EXISTS  `copilot_server_context` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `context_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '上下文id',
  `session_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '上下文归属的会话id',
  `chat_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '上下文归属的聊天窗id',
  `username` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '用户名',
  `create_time` datetime DEFAULT NULL COMMENT '聊天窗口创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `last_access_time` datetime DEFAULT NULL COMMENT '最近一次提问时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


-- copilot_sit.copilot_server_dialog definition

CREATE TABLE  IF NOT EXISTS  `copilot_server_dialog` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `dialog_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '对话id',
  `ask_content` longtext COLLATE utf8mb4_bin NOT NULL COMMENT '提问内容',
  `answer_content` longtext COLLATE utf8mb4_bin COMMENT '回答内容',
  `create_time` datetime DEFAULT NULL COMMENT '提问生成时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `context_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '对话上下文id',
  `like_status` varchar(32) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '点赞',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


-- copilot_sit.copilot_server_dialog_task definition

CREATE TABLE  IF NOT EXISTS  `copilot_server_dialog_task` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `task_id` longtext COLLATE utf8mb4_bin NOT NULL COMMENT '对话任务id',
  `dialog_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '对话id',
  `status` varchar(32) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '提问状态',
  `errorMessage` text COLLATE utf8mb4_bin COMMENT '错误信息',
  `finished_time` datetime DEFAULT NULL COMMENT '回答生成时间',
  `create_time` datetime DEFAULT NULL COMMENT '聊天窗口创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


-- copilot_sit.copilot_server_llm_client definition

CREATE TABLE  IF NOT EXISTS  `copilot_server_llm_client` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `route_regex` varchar(128) COLLATE utf8mb4_bin NOT NULL,
  `url` varchar(512) COLLATE utf8mb4_bin NOT NULL COMMENT 'url',
  `status` varchar(32) COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'status',
  `name` varchar(128) COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'name',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `offline_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '下线时间',
  `config` text COLLATE utf8mb4_bin,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


-- copilot_sit.copilot_server_prompt_template definition

CREATE TABLE  IF NOT EXISTS  `copilot_server_prompt_template` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `prompt_type` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT 'prompt类型',
  `desc` varchar(256) COLLATE utf8mb4_bin NOT NULL COMMENT '描述',
  `icon` longtext COLLATE utf8mb4_bin COMMENT 'icon',
  `title` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '标题',
  `name` varchar(128) COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'name',
  `tip` varchar(128) COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'tip',
  `template` longtext COLLATE utf8mb4_bin COMMENT 'template',
  `example` longtext COLLATE utf8mb4_bin COMMENT 'example',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',
  `collection_name` varchar(256) COLLATE utf8mb4_bin DEFAULT NULL,
  `top_n` int(11) DEFAULT NULL,
  `shield` int(11) NOT NULL COMMENT '0展示，1不展示',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


-- copilot_sit.copilot_server_session definition

CREATE TABLE  IF NOT EXISTS  `copilot_server_session` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `session_id` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '会话id',
  `username` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '用户名',
  `chat_app` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '聊天应用',
  `cookies` text COLLATE utf8mb4_bin COMMENT 'cookie',
  `workspace_id` int(11) DEFAULT NULL COMMENT '工作空间id',
  `department` varchar(32) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '部门',
  `roles` text COLLATE utf8mb4_bin COMMENT '角色列表',
  `proxy_user` varchar(32) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '代理用户',
  `create_time` datetime DEFAULT NULL COMMENT '聊天会话创建时间',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `closed` tinyint(4) DEFAULT NULL COMMENT '是否关闭，1打开，0关闭',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- 用于记录各个项目的git读写用户名
